    model_config = ConfigDict(extra="forbid", frozen=True, str_strip_whitespace=True)

    chapter_contract_id: StableId
    node_id: StableId
    template_id: StableId
    template_sha256: Sha256
    resolved_facts: Mapping[str, str] = Field(min_length=1)
