        if len(cell_ids) != len(set(cell_ids)):
            raise ValueError("cells must not contain duplicate cell ids")
        return value

    def is_material(self) -> bool:
        return bool((self.text or "").strip()) or any(
            (cell.value or "").strip() for cell in self.cells
        )


