REGISTRY_SCHEMA_VERSION = "protocol-v3-chapter-registry.v1"

_BATCH_REQUIRED_KEYS = (
    "schema_version",
    "generated_for",
    "authority",
    "template_id",
    "template_sha256",
    "fact_vocabulary",
    "claim_vocabulary",
    "coverage_roles",
    "fixtures",
