    assert {"statistics.interim.timing", "statistics.interim.information_fraction", "statistics.interim.purpose", "statistics.interim.decision_responsibility", "statistics.interim.final_analysis_impact"} <= ip
    assert any("efficacy" in item.fact_path for item in interim.substantive_content.fact_requirements)
