    await Bun.write(sp,JSON.stringify(s,null,2)+'\n');
  }
  for (const fixture of batch6.fixtures) {
    for (const obj of fixture.content.objects || []) for (const cell of obj.cells || []) cell.cell_id=cell.cell_id.replaceAll('sample-size:','sample_size:').replaceAll('analysis-set:','analysis_set:');
  }
  await Bun.write('tests/fixtures/protocol_v3/chapter_content_v2/batch6.json',JSON.stringify(batch6,null,2)+'\n');
};
await normalizeV2CellsAndMarkers();
display('normalized cell namespaces and parent inheritance markers');

